-- Enseres, sin fotos ajenas. Las piezas de ejemplo llevaban fotos de otras
-- hermandades sacadas de Wikimedia Commons, con el pie «Foto de ejemplo · Wikimedia Commons, CC BY-SA». Esa licencia
-- exige el autor y el enlace a cada original, y no se apuntaron: no se pueden
-- publicar. Se cambian por fotos del Grupo (public/images/enseres, recortadas
-- de las cabeceras y del trono) y se quitan las tres piezas que no tienen una
-- propia que encaje (simpecado, libro de reglas e incensario). Los autores y
-- los años siguen siendo DE EJEMPLO.

-- 1. El carrusel que sigue tal como lo puso enseres_en_carrusel: piezas nuevas.
UPDATE `ContenidoPagina`
SET `datos` = JSON_SET(`datos`, '$.bloques[1].piezas', JSON_EXTRACT('[{"familia":"Insignias","titulo":"Cruz de guía","texto":"Abre el cortejo y marca el camino. Madera con cantoneras y escudo de metal plateado, entre los primeros nazarenos.","foto":{"url":"/images/enseres/cruz-de-guia.webp","alt":"La cruz de guía del Grupo, entre los nazarenos y los banderines","pie":""},"datos":[{"etiqueta":"Autor","valor":"Orfebrería Hermanos Lozano"},{"etiqueta":"Año","valor":"1997"},{"etiqueta":"Materiales","valor":"Madera, metal plateado"}]},{"familia":"Insignias","titulo":"Banderines","texto":"Acompañan a la cruz de guía en el primer tramo. Cada uno lleva su relieve en metal plateado sobre terciopelo negro y su número en la punta.","foto":{"url":"/images/enseres/banderines.webp","alt":"Los banderines del cortejo, de noche, con sus relieves de metal plateado","pie":""},"datos":[{"etiqueta":"Bordado","valor":"Taller de bordado de la Esperanza"},{"etiqueta":"Año","valor":"2004"},{"etiqueta":"Materiales","valor":"Terciopelo, metal plateado"}]},{"familia":"Bordado","titulo":"Manto de salida","texto":"Terciopelo azul noche bordado en oro y plata, con el anagrama repetido por toda la cola. Se restauró en 2018.","foto":{"url":"/images/enseres/manto-de-salida.webp","alt":"Detalle del manto azul de la Virgen, bordado en oro y plata","pie":""},"datos":[{"etiqueta":"Bordado","valor":"Taller de bordado de la Esperanza"},{"etiqueta":"Año","valor":"1976, restaurado en 2018"},{"etiqueta":"Materiales","valor":"Terciopelo, oro fino"}]},{"familia":"Trono","titulo":"Candelería","texto":"La cera del trono lleva el escudo del Grupo. Se enciende al anochecer, el Sábado de Pasión, y alumbra la cara de la Virgen.","foto":{"url":"/images/enseres/candeleria.webp","alt":"Cirios del trono con el escudo del Grupo, delante de la Virgen","pie":""},"datos":[{"etiqueta":"Orfebre","valor":"Talleres Marín"},{"etiqueta":"Año","valor":"2021"},{"etiqueta":"Piezas","valor":"64 candeleros"}]},{"familia":"Trono","titulo":"Trono de la Virgen","texto":"La pieza mayor del Grupo. Caoba, metal plateado, jarras y candelería, portado por su cuadrilla.","foto":{"url":"/images/trono-candeleria.webp","alt":"El trono de la Virgen de los Desamparados, con la candelería","pie":""},"datos":[{"etiqueta":"Autor","valor":"Talleres Marín"},{"etiqueta":"Año","valor":"2008"},{"etiqueta":"Materiales","valor":"Caoba, metal plateado"}]}]', '$'))
WHERE `slug` = 'enseres'
  AND JSON_EQUALS(JSON_EXTRACT(`datos`, '$.bloques[1].piezas'), JSON_EXTRACT('[{"familia":"Insignias","titulo":"Cruz de guía","texto":"Abre el cortejo y marca el camino. Madera forrada de metal dorado, con los atributos de la Pasión en relieve.","foto":{"url":"/images/enseres/cruz.webp","alt":"Cruz de guía dorada, con los atributos de la Pasión en relieve","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Autor","valor":"Orfebrería Hermanos Lozano"},{"etiqueta":"Año","valor":"1997"},{"etiqueta":"Materiales","valor":"Madera, metal dorado"}]},{"familia":"Insignias","titulo":"Estandarte corporativo","texto":"La insignia que representa al Grupo. Bordado en oro sobre terciopelo morado, con el Crucificado en el óvalo central.","foto":{"url":"/images/enseres/estandarte.webp","alt":"Estandarte morado bordado en oro, con un crucificado en el centro","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Bordado","valor":"Taller de bordado de la Esperanza"},{"etiqueta":"Año","valor":"2004"},{"etiqueta":"Materiales","valor":"Terciopelo, oro fino"}]},{"familia":"Insignias","titulo":"Simpecado","texto":"Precede al trono de la Virgen. Terciopelo granate bordado en oro, con la imagen de la Señora pintada al óleo.","foto":{"url":"/images/enseres/simpecado.webp","alt":"Simpecado granate bordado en oro, con la Virgen pintada en el centro","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Bordado","valor":"Hermanas camareras"},{"etiqueta":"Año","valor":"2011"},{"etiqueta":"Procedencia","valor":"Donación"}]},{"familia":"Archivo","titulo":"Libro de Reglas","texto":"Guarda las reglas aprobadas por el Obispado. Tapas de terciopelo con cantoneras y escudo en plata de ley.","foto":{"url":"/images/enseres/reglas.webp","alt":"Tapas de terciopelo azul con cantoneras y escudo de plata","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Orfebre","valor":"Talleres Marín"},{"etiqueta":"Año","valor":"1989"},{"etiqueta":"Materiales","valor":"Terciopelo, plata de ley"}]},{"familia":"Orfebrería","titulo":"Incensario y naveta","texto":"El humo del incienso abre paso a la Virgen. Incensario y naveta de metal plateado, cincelados a mano.","foto":{"url":"/images/enseres/incensario.webp","alt":"Incensario humeante y naveta de plata, con sus cadenas","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Orfebre","valor":"Orfebrería Hermanos Lozano"},{"etiqueta":"Año","valor":"2015"}]},{"familia":"Bordado","titulo":"Manto de salida","texto":"Hojarasca de oro sobre terciopelo negro. Se restauró en 2018 y se pasó a terciopelo nuevo.","foto":{"url":"/images/enseres/manto.webp","alt":"Detalle del bordado en oro del manto, con flores y hojas sobre terciopelo negro","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Bordado","valor":"Taller de bordado de la Esperanza"},{"etiqueta":"Año","valor":"1976, restaurado en 2018"},{"etiqueta":"Materiales","valor":"Terciopelo, oro fino"}]},{"familia":"Trono","titulo":"Palio y candelería","texto":"Doce varales y candelería de metal plateado: la luz de la cera sobre la Virgen, el Sábado de Pasión.","foto":{"url":"/images/enseres/palio.webp","alt":"Palio de noche, con la candelería encendida delante de la Virgen","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Orfebre","valor":"Talleres Marín"},{"etiqueta":"Año","valor":"2021"},{"etiqueta":"Piezas","valor":"12 varales, 64 candeleros"}]},{"familia":"Trono","titulo":"Trono de la Virgen","texto":"La pieza mayor del Grupo. Caoba, metal plateado, jarras y candelería, portado por su cuadrilla.","foto":{"url":"/images/trono-candeleria.webp","alt":"El trono de la Virgen de los Desamparados, con la candelería","pie":""},"datos":[{"etiqueta":"Autor","valor":"Talleres Marín"},{"etiqueta":"Año","valor":"2008"},{"etiqueta":"Materiales","valor":"Caoba, metal plateado"}]}]', '$'));

-- 2. Si alguien ya lo había tocado en el CMS, se respeta lo suyo: solo se
-- quitan las piezas cuya foto no tiene sustituta, una a una, en cualquier
-- carrusel de cualquier página.
UPDATE `ContenidoPagina`
SET `datos` = JSON_REMOVE(`datos`, REPLACE(JSON_UNQUOTE(JSON_SEARCH(`datos`, 'one', '/images/enseres/simpecado.webp')), '.foto.url', ''))
WHERE JSON_UNQUOTE(JSON_SEARCH(`datos`, 'one', '/images/enseres/simpecado.webp')) LIKE '%.piezas[%].foto.url';
UPDATE `ContenidoPagina`
SET `datos` = JSON_REMOVE(`datos`, REPLACE(JSON_UNQUOTE(JSON_SEARCH(`datos`, 'one', '/images/enseres/reglas.webp')), '.foto.url', ''))
WHERE JSON_UNQUOTE(JSON_SEARCH(`datos`, 'one', '/images/enseres/reglas.webp')) LIKE '%.piezas[%].foto.url';
UPDATE `ContenidoPagina`
SET `datos` = JSON_REMOVE(`datos`, REPLACE(JSON_UNQUOTE(JSON_SEARCH(`datos`, 'one', '/images/enseres/incensario.webp')), '.foto.url', ''))
WHERE JSON_UNQUOTE(JSON_SEARCH(`datos`, 'one', '/images/enseres/incensario.webp')) LIKE '%.piezas[%].foto.url';

-- 3. Las demás fotos, a su sustituta, y fuera el pie de Commons. También en el
-- historial y en las secciones guardadas: volver a una versión antigua no debe
-- traer de vuelta una foto que ya no está. (Una versión antigua con una de las
-- tres piezas quitadas la enseñará sin foto: no hay otra que poner.)
UPDATE `ContenidoPagina` SET `datos` = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`datos`, '"/images/enseres/cruz.webp"', '"/images/enseres/cruz-de-guia.webp"'), '"/images/enseres/estandarte.webp"', '"/images/enseres/banderines.webp"'), '"/images/enseres/manto.webp"', '"/images/enseres/manto-de-salida.webp"'), '"/images/enseres/palio.webp"', '"/images/enseres/candeleria.webp"'), '"pie": "Foto de ejemplo · Wikimedia Commons, CC BY-SA"', '"pie": ""'), '"pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"', '"pie":""')
WHERE `datos` LIKE '%/images/enseres/%';
UPDATE `VersionContenido` SET `datos` = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`datos`, '"/images/enseres/cruz.webp"', '"/images/enseres/cruz-de-guia.webp"'), '"/images/enseres/estandarte.webp"', '"/images/enseres/banderines.webp"'), '"/images/enseres/manto.webp"', '"/images/enseres/manto-de-salida.webp"'), '"/images/enseres/palio.webp"', '"/images/enseres/candeleria.webp"'), '"pie": "Foto de ejemplo · Wikimedia Commons, CC BY-SA"', '"pie": ""'), '"pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"', '"pie":""')
WHERE `datos` LIKE '%/images/enseres/%';
UPDATE `SeccionGuardada` SET `bloques` = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`bloques`, '"/images/enseres/cruz.webp"', '"/images/enseres/cruz-de-guia.webp"'), '"/images/enseres/estandarte.webp"', '"/images/enseres/banderines.webp"'), '"/images/enseres/manto.webp"', '"/images/enseres/manto-de-salida.webp"'), '"/images/enseres/palio.webp"', '"/images/enseres/candeleria.webp"'), '"pie": "Foto de ejemplo · Wikimedia Commons, CC BY-SA"', '"pie": ""'), '"pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"', '"pie":""')
WHERE `bloques` LIKE '%/images/enseres/%';
